package main

import (
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
)

type model struct{ text string; n int }

func (m model) Init() tea.Cmd { return nil }

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if k, ok := msg.(tea.KeyMsg); ok {
		switch k.String() {
		case "q", "ctrl+c": return m, tea.Quit
		case " ": m.n++
		}
	}
	return m, nil
}

func (m model) View() string { return fmt.Sprintf("%s\nspace: %d, q to quit\n", m.text, m.n) }

func main() { tea.NewProgram(model{text: "{{initial_text}}"}).Run() }
